mapper.update:
update team_match_participant
set attendance = #{attendance}
where team_match_id = #{teamMatchId}
  and team_id = #{teamId}

update team_match_participant
set status = '취소',
	cancelled_at = now(),
	cancel_reason = #{cancelReason}
where team_match_id = #{teamMatchId}
	and user_id = #{userId}
    and status = '결제완료'
